{"cards": [{"node_code": "N_4114520ca8093059", "definition": "研究全身性严重过敏反应（如过敏性休克、严重血管性水肿）的病理生理机制、临床识别、紧急救治流程及长期预防管理的学科分支。", "boundary": "本节点聚焦于危及生命的全身性过敏反应，强调急救措施（如肾上腺素使用、气道管理）及高危人群管理。不涵盖局限于单一器官系统的轻度或中度过敏症状，也不涵盖非免疫介导的类过敏反应（anaphylactoid reactions），除非涉及鉴别诊断。", "includes": ["过敏性休克的急救处理与复苏", "严重血管性水肿的诊断与鉴别", "过敏原暴露后的长期预防与患者教育"], "excludes": ["局限于皮肤或呼吸道的非危及生命过敏反应", "非免疫机制引起的类过敏反应"], "sibling_distinctions": [{"other_code": "N_47c28843acb066b5", "rule": "呼吸道过敏侧重慢性或急性呼吸道局部症状（如哮喘、鼻炎）；本节点侧重全身性、危及生命的系统性反应。"}, {"other_code": "N_29ccf53a6865c293", "rule": "皮肤与消化道过敏侧重局部器官表现；本节点侧重多系统受累且危及生命的严重全身反应。"}], "cross_boundary_rule": "若过敏反应仅表现为呼吸道或皮肤症状，主挂载相应局部过敏节点；若出现低血压、意识障碍等全身性休克表现，主挂载本节点。"}, {"node_code": "N_47c28843acb066b5", "definition": "研究由过敏原引发的上呼吸道（如过敏性鼻炎）和下呼吸道（如过敏性哮喘）炎症反应的机制、诊断标准及长期控制策略的学科分支。", "boundary": "本节点涵盖鼻、咽、喉、气管及支气管的过敏性炎症，重点在于气道高反应性的管理与症状控制。不涵盖由感染、肿瘤或非免疫性刺激引起的呼吸道疾病，也不涵盖全身性严重过敏反应，除非作为呼吸道症状的严重进展。", "includes": ["过敏性鼻炎的鼻内镜检查与药物治疗", "过敏性哮喘的肺功能评估与吸入剂管理", "职业性呼吸道过敏的预防与干预"], "excludes": ["感染性鼻炎或支气管炎", "非过敏介导的慢性阻塞性肺疾病（COPD）"], "sibling_distinctions": [{"other_code": "N_4114520ca8093059", "rule": "本节点侧重呼吸道局部慢性或急性炎症管理；严重过敏节点侧重全身性危及生命的休克反应。"}, {"other_code": "N_29ccf53a6865c293", "rule": "本节点聚焦呼吸道黏膜；皮肤与消化道节点聚焦皮肤及胃肠黏膜，两者解剖部位不同。"}], "cross_boundary_rule": "涉及哮喘的免疫机制基础理论研究主挂载免疫学；涉及哮喘的临床症状控制、吸入剂使用及过敏原回避主挂载本节点。"}, {"node_code": "N_29ccf53a6865c293", "definition": "研究由过敏原引发的皮肤（如特应性皮炎、荨麻疹）及消化道（如食物过敏、嗜酸性食管炎）炎症反应的机制、诊断与治疗的学科分支。", "boundary": "本节点涵盖皮肤及胃肠道黏膜的过敏性疾病，重点在于局部症状缓解、营养管理及生活质量改善。不涵盖由感染、自身免疫或遗传因素引起的非过敏性皮肤病或胃肠病，也不涵盖全身性严重过敏反应，除非作为局部症状的严重进展。", "includes": ["特应性皮炎的皮肤屏障修复与免疫调节治疗", "食物过敏的回避饮食与口服免疫治疗", "慢性荨麻疹的抗组胺药阶梯治疗"], "excludes": ["感染性皮疹或胃肠炎", "系统性红斑狼疮等自身免疫性皮肤或胃肠表现"], "sibling_distinctions": [{"other_code": "N_47c28843acb066b5", "rule": "本节点聚焦皮肤及消化道黏膜；呼吸道节点聚焦鼻、咽、喉、气管及支气管，两者解剖部位不同。"}, {"other_code": "N_4114520ca8093059", "rule": "本节点侧重局部器官系统的慢性或急性管理；严重过敏节点侧重全身性危及生命的休克反应。"}], "cross_boundary_rule": "涉及食物过敏的免疫机制研究主挂载免疫学；涉及食物过敏的临床饮食管理、皮肤症状治疗主挂载本节点。"}]}
